package main

import (
	"encoding/json"
	"fmt"
	"io"
	"os"

	plugin "github.com/SemRels/analyzer-default/internal/plugin"
)

func main() {
	os.Exit(run(os.Stdout, os.Stderr, os.LookupEnv))
}

func run(stdout, stderr io.Writer, lookupEnv func(string) (string, bool)) int {
	dryRunVal, _ := lookupEnv("SEMREL_DRY_RUN")
	dryRun := dryRunVal == "true"
	if dryRun {
		_, _ = fmt.Fprintf(stderr, "plugin_schema_version=%d\n", plugin.PluginSchemaVersion)
	}

	raw, _ := lookupEnv("SEMREL_COMMITS")

	var commits []string
	if raw != "" {
		if err := json.Unmarshal([]byte(raw), &commits); err != nil {
			_, _ = fmt.Fprintln(stderr, "analyzer-default: invalid SEMREL_COMMITS JSON:", err)
			return 1
		}
	}

	analyzer, err := plugin.NewFromEnv(lookupEnv)
	if err != nil {
		_, _ = fmt.Fprintln(stderr, "analyzer-default:", err)
		return 1
	}

	result := analyzer.Analyze(commits)
	result.PluginSchemaVersion = plugin.PluginSchemaVersion

	if dryRun {
		_, _ = fmt.Fprintf(stderr, "[dry-run] analyzer-default: decision=%s (%s)\n", result.Bump, result.Reason)
	}

	if err := json.NewEncoder(stdout).Encode(result); err != nil {
		_, _ = fmt.Fprintln(stderr, "analyzer-default:", err)
		return 1
	}

	return 0
}
